const brandMemory = Array.isArray($json) ? $json : [$json];
const request = $('Webhook').first().json;

// Group brand memory by category
const grouped = brandMemory.reduce((acc, item) => {
  if (!acc[item.categoria]) acc[item.categoria] = [];
  acc[item.categoria].push({ clave: item.clave, valor: item.valor });
  return acc;
}, {});

const section = (title, items) => items && items.length
  ? `\n## ${title}\n` + items.map(i => `- ${i.clave}: ${i.valor}`).join('\n')
  : '';

const systemPrompt = `Eres el asistente de contenido de Zecamo Studios. Generás contenido de alta calidad para redes sociales basado en la memoria de marca de la agencia.${section('TONO Y ESTILO', grouped.tono)}${section('POSICIONAMIENTO', grouped.posicionamiento)}${section('SERVICIOS', grouped.servicios)}${section('AUDIENCIA OBJETIVO', grouped.audiencia)}${section('PILARES DE CONTENIDO', grouped.pilares)}${section('FRAMEWORKS', grouped.frameworks)}${section('CTA PATTERNS', grouped.cta_patterns)}${section('VOCABULARIO A USAR', grouped.vocabulario)}${section('RESTRICCIONES', grouped.restricciones)}

## INSTRUCCIONES
- Plataforma objetivo: ${request.plataforma || 'linkedin'}
- Tipo de contenido: ${request.tipo || 'post'}
- Pilar: ${request.pillar || 'no especificado'}
- Generá contenido original que refleje exactamente el tono y posicionamiento de la marca.
- El post debe incluir: hook impactante, desarrollo con valor real, CTA claro.
- Para LinkedIn: máximo 1300 caracteres, formato de párrafos cortos.
- Para Instagram: máximo 2200 caracteres, incluir hashtags relevantes.
- Para Twitter: máximo 280 caracteres, directo e impactante.
- Respondé SOLO con el contenido del post, sin explicaciones adicionales.`;

return [{ json: {
  systemPrompt,
  userPrompt: request.prompt || `Generá un post sobre automatización con IA para ${request.plataforma || 'linkedin'}`,
  plataforma: request.plataforma || 'linkedin',
  tipo: request.tipo || 'post',
  pillar: request.pillar || null,
  existingPostId: request.post_id || null,
  brandMemoryCount: brandMemory.length
} }];

const openaiResponse = $json;
const request = $('Build System Prompt').first().json;

const choice = openaiResponse.choices && openaiResponse.choices[0];
const contenido = choice?.message?.content || '';
const usage = openaiResponse.usage || {};
const tokensIn = usage.prompt_tokens || 0;
const tokensOut = usage.completion_tokens || 0;
const modelo = openaiResponse.model || 'gpt-4o';

// Extract hook (first 200 chars or first line)
const lines = contenido.split('\n').filter(l => l.trim());
const hook = lines[0]?.substring(0, 200) || contenido.substring(0, 200);

// Extract CTA (last line or sentence with action words)
const lastLine = lines[lines.length - 1] || '';
const ctaPatterns = /\?|DM|escribi|escribime|contáctame|empezamos|agendá|reservá/i;
const cta = ctaPatterns.test(lastLine) ? lastLine : lines.find(l => ctaPatterns.test(l)) || '';

// Extract hashtags
const hashtagMatches = contenido.match(/#[\w\u00C0-\u024F]+/g) || [];
const hashtags = [...new Set(hashtagMatches)];

// Score (0-100)
let score = 0;
if (contenido.length > 100) score += 20;
if (hook && hook.length > 20) score += 20;
if (cta && cta.length > 5) score += 20;
if (hashtags.length >= 3) score += 20;
if (contenido.includes('?') || contenido.match(/[!¿]/)) score += 10;
if (tokensOut > 200) score += 10;

return [{ json: {
  contenido,
  hook,
  cta,
  hashtags,
  ai_score: score,
  ai_feedback: `Generated with ${modelo}. Score: ${score}/100. Tokens: ${tokensIn} in / ${tokensOut} out.`,
  tokens_in: tokensIn,
  tokens_out: tokensOut,
  modelo,
  plataforma: request.plataforma,
  tipo: request.tipo,
  pillar: request.pillar,
  existingPostId: request.existingPostId,
  userPrompt: request.userPrompt
} }];

const postResponse = Array.isArray($json) ? $json[0] : $json;
const genData = $('Parse AI Response').first().json;
return [{ json: {
  post_id: postResponse.id,
  contenido: genData.contenido,
  hook: genData.hook,
  cta: genData.cta,
  hashtags: genData.hashtags,
  ai_score: genData.ai_score,
  tokens_in: genData.tokens_in,
  tokens_out: genData.tokens_out,
  modelo: genData.modelo,
  plataforma: genData.plataforma,
  tipo: genData.tipo,
  userPrompt: genData.userPrompt
} }];
